
/* Stage 16.1 — RM0 + China-compatible PWA foundation.
   Keep course content independent from hosting, authentication and backend vendors.
   The app is local-first: learning can continue from browser storage, while a
   future sync adapter can be added without rewriting the course content. */
const APP_CONFIG={
  appId:'bece1064-young-childrens-literature',
  appVersion:'16.4.0',
  architecture:'local-first-backend-neutral',
  deploymentGoal:'china-compatible-pwa',
    costGoal:'RM0',
    storageVersion:1,
    offlineVersion:'16.4.0',
    serviceWorker:'./sw.js',
    manifest:'./manifest.webmanifest'
};
const AppStorage={
  prefix:'',
  dbName:'BECE1064_LocalData',
  storeName:'appState',
  get(key,fallback=null){
    try{
      const raw=localStorage.getItem(this.prefix+key);
      return raw===null?fallback:JSON.parse(raw);
    }catch(e){return fallback}
  },
  set(key,value){
    try{
      localStorage.setItem(this.prefix+key,JSON.stringify(value));
      this._mirror(key,value);
      return true;
    }catch(e){return false}
  },
  remove(key){
    try{
      localStorage.removeItem(this.prefix+key);
      this._removeMirror(key);
      return true;
    }catch(e){return false}
  },
  has(key){
    try{return localStorage.getItem(this.prefix+key)!==null}catch(e){return false}
  },
  getItem(key){return localStorage.getItem(this.prefix+key)},
  setItem(key,value){try{localStorage.setItem(this.prefix+key,value);this._mirrorRaw(key,value);return true}catch(e){return false}},
  removeItem(key){try{localStorage.removeItem(this.prefix+key);this._removeMirror(key);return true}catch(e){return false}},
  _open(){
    if(!('indexedDB' in window))return Promise.resolve(null);
    return new Promise(resolve=>{
      const request=indexedDB.open(this.dbName,1);
      request.onupgradeneeded=()=>request.result.createObjectStore(this.storeName,{keyPath:'key'});
      request.onsuccess=()=>resolve(request.result);
      request.onerror=()=>resolve(null);
    });
  },
  _mirror(key,value){
    this._mirrorRaw(key,JSON.stringify(value));
  },
  _mirrorRaw(key,raw){
    this._open().then(db=>{
      if(!db)return;
      try{
        const tx=db.transaction(this.storeName,'readwrite');
        tx.objectStore(this.storeName).put({key:key,value:raw,savedAt:Date.now()});
      }catch(e){}
    });
  },
  _removeMirror(key){
    this._open().then(db=>{
      if(!db)return;
      try{db.transaction(this.storeName,'readwrite').objectStore(this.storeName).delete(key)}catch(e){}
    });
  },
  async hydrate(){
    const db=await this._open();
    if(!db)return;
    return new Promise(resolve=>{
      try{
        const req=db.transaction(this.storeName,'readonly').objectStore(this.storeName).getAll();
        req.onsuccess=()=>{
          (req.result||[]).forEach(record=>{
            if(localStorage.getItem(record.key)===null){
              try{nativeStorageSetItem.call(localStorage,record.key,record.value)}catch(e){}
            }
          });
          resolve(true);
        };
        req.onerror=()=>resolve(false);
      }catch(e){resolve(false)}
    });
  }
};
const AppRuntime={
  online:navigator.onLine!==false,
  storage:'localStorage',
  sync:'local-only',
  setOnline(v){
    this.online=v;
    const el=document.getElementById('connectionStatus');
    if(el){
      el.innerHTML=v
        ? 'Online • 本地学习数据已保存 • Zàixiàn • Běndì xuéxí shùjù yǐ bǎocún'
        : 'Offline • 本地学习仍可继续 • Líxiàn • Běndì xuéxí réng kě jìxù';
      el.setAttribute('data-online',v?'true':'false');
    }
  }
};
const OfflineEngine={
  supported:('serviceWorker' in navigator),
  registration:null,
  status:'starting',
  async start(){
    if(!this.supported){this.status='unsupported';return false}
    if(location.protocol==='file:'){this.status='preview';return false}
    try{
      this.registration=await navigator.serviceWorker.register(APP_CONFIG.serviceWorker,{scope:'./'});
      this.status=navigator.serviceWorker.controller?'ready':'registered';
      navigator.serviceWorker.addEventListener('controllerchange',()=>{this.status='ready';this.updateIndicator()});
      this.updateIndicator();
      return true
    }catch(e){this.status='error';this.updateIndicator();return false}
  },
  updateIndicator(){
    const el=document.getElementById('offlineStatus');
    if(!el)return;
    const online=navigator.onLine;
    let en=online?'Online':'Offline',cn=online?'在线':'离线',py=online?'Zàixiàn':'Líxiàn';
    if(this.status==='ready'||this.status==='registered'){en+=online?' • Offline ready':' • Offline mode';cn+=online?' • 可离线使用':' • 离线模式';py+=online?' • Kě líxiàn shǐyòng':' • Líxiàn móshì'}
    else if(this.status==='preview'){en+=' • Preview mode';cn+=' • 预览模式';py+=' • Yùlǎn móshì'}
    else if(this.status==='unsupported'||this.status==='error'){en+=' • Offline engine unavailable';cn+=' • 离线引擎不可用';py+=' • Líxiàn yǐnqíng bù kěyòng'}
    el.innerHTML=en+'<br>'+cn+'<br>'+py;
    el.className='statusLive'
  }
};
/* Compatibility bridge: existing course features can keep their simple
   localStorage calls while every write is also mirrored to IndexedDB.
   This lets us strengthen the data layer without rewriting the course UI. */
const nativeStorageSetItem=Storage.prototype.setItem;
const nativeStorageRemoveItem=Storage.prototype.removeItem;
Storage.prototype.setItem=function(key,value){
  nativeStorageSetItem.call(this,key,value);
  if(this===window.localStorage && window.AppStorageReady!==false){
    try{AppStorage._mirrorRaw(key,value)}catch(e){}
  }
};
Storage.prototype.removeItem=function(key){
  nativeStorageRemoveItem.call(this,key);
  if(this===window.localStorage && window.AppStorageReady!==false){
    try{AppStorage._removeMirror(key)}catch(e){}
  }
};
window.AppStorageReady=true;
const InstallExperience={
  deferredPrompt:null,
  standalone:false,
  ios:false,
  init(){
    this.standalone=window.matchMedia('(display-mode: standalone)').matches||window.navigator.standalone===true;
    this.ios=/iphone|ipad|ipod/i.test(navigator.userAgent)&&!this.standalone;
    const btn=document.getElementById('installAppBtn');
    if(btn)btn.onclick=()=>this.install();
    window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();this.deferredPrompt=e;this.update()});
    window.addEventListener('appinstalled',()=>{this.deferredPrompt=null;this.standalone=true;this.update()});
    const media=window.matchMedia('(display-mode: standalone)');
    media.addEventListener?.('change',()=>{this.standalone=media.matches;this.update()});
    this.update();
  },
  async install(){
    if(this.deferredPrompt){
      this.deferredPrompt.prompt();
      const result=await this.deferredPrompt.userChoice;
      if(result?.outcome==='accepted')this.deferredPrompt=null;
      this.update();
      return;
    }
    this.update(true);
  },
  update(showHelp=false){
    const btn=document.getElementById('installAppBtn'),state=document.getElementById('installState');
    if(!btn||!state)return;
    if(this.standalone){
      btn.classList.remove('show');
      state.innerHTML='Installed app<br>已安装应用<br>Yǐ ānzhuāng yìngyòng';
      return;
    }
    if(this.deferredPrompt){
      btn.classList.add('show');
      state.innerHTML='Install for quick access and offline use.<br>安装后可快速访问并离线使用。<br>Ānzhuāng hòu kě kuàisù fǎngwèn bìng líxiàn shǐyòng.';
      return;
    }
    btn.classList.toggle('show',this.ios||showHelp);
    state.innerHTML=this.ios||showHelp
      ? 'On iPhone/iPad: use Share → Add to Home Screen.<br>在 iPhone/iPad：使用“分享”→“添加到主屏幕”。<br>Zài iPhone/iPad: shǐyòng “Fēnxiǎng” → “Tiānjiā dào zhǔpíngmù”.'
      : 'Install option appears when your browser supports PWA installation.<br>浏览器支持 PWA 安装时会显示安装选项。<br>Liúlǎnqì zhīchí PWA ānzhuāng shí huì xiǎnshì ānzhuāng xuǎnxiàng.';
  }
};
function initialiseAppFoundation(){
  document.documentElement.dataset.appVersion=APP_CONFIG.appVersion;
  document.documentElement.dataset.architecture=APP_CONFIG.architecture;
  AppStorage.set('meta',{appId:APP_CONFIG.appId,version:APP_CONFIG.appVersion,storageVersion:APP_CONFIG.storageVersion});
  AppStorage.hydrate().then(()=>{syncAllProgress();setupAccessibility()});
  InstallExperience.init();
  window.addEventListener('online',()=>{AppRuntime.setOnline(true);OfflineEngine.updateIndicator()});
  window.addEventListener('offline',()=>{AppRuntime.setOnline(false);OfflineEngine.updateIndicator()});
  AppRuntime.setOnline(AppRuntime.online);
  OfflineEngine.start();
}
