const lessonData={0:{out:['Identify the value and purposes of literature for children from infancy to age six.','Explain how literature can support development, imagination and a love of reading.'],cn:['识别从婴儿期到六岁儿童文学的价值和目的。','解释文学如何支持儿童的发展、想象力和阅读兴趣。'],py:['Shíbié cóng yīng’ér qī dào liù suì értóng wénxué de jiàzhí hé mùdì.','Jiěshì wénxué rúhé zhīchí értóng de fāzhǎn, xiǎngxiànglì hé yuèdú xìngqù.']},1:{out:['Explain three criteria for judging a quality picture book.','Apply the criteria to a simple book-review activity.'],cn:['说明评价优质图画书的三个标准。','把这些标准应用到简单的图书评价活动中。'],py:['Shuōmíng píngjià yōuzhì túhuàshū de sān gè biāozhǔn.','Bǎ zhèxiē biāozhǔn yìngyòng dào jiǎndān de túshū píngjià huódòng zhōng.']},2:{out:['Identify common paratext and visual features.','Explain how illustrations add meaning beyond the words.'],cn:['识别常见的副文本和视觉特征。','解释插图如何在文字之外增加意义。'],py:['Shíbié chángjiàn de fù wénběn hé shìjué tèzhēng.','Jiěshì chātú rúhé zài wénzì zhīwài zēngjiā yìyì.']},3:{out:['Differentiate major early book formats and genres.','Choose a suitable format for a simple learning purpose.'],cn:['区分主要的早期图书形式和体裁。','根据简单的学习目的选择合适的图书形式。'],py:['Qūfēn zhǔyào de zǎoqī túshū xíngshì hé tǐcái.','Gēnjù jiǎndān de xuéxí mùdì xuǎnzé héshì de túshū xíngshì.']},4:{out:['Explain how rhythm, rhyme and sound support young children’s enjoyment of poetry.','Select and present a short poem, nursery rhyme or song for young children.'],cn:['解释节奏、押韵和声音如何支持幼儿享受诗歌。','为幼儿选择并呈现一首短诗、童谣或歌曲。'],py:['Jiěshì jiézòu, yāyùn hé shēngyīn rúhé zhīchí yòu’ér xiǎngshòu shīgē.','Wèi yòu’ér xuǎnzé bìng chéngxiàn yì shǒu duǎnshī, tóngyáo huò gēqǔ.']},5:{out:['Apply developmental, cultural, language and interest criteria when selecting books.','Justify an inclusive book choice for a young child or group.'],cn:['应用发展、文化、语言和兴趣标准选择图书。','为幼儿或儿童小组说明包容性选书的理由。'],py:['Yìngyòng fāzhǎn, wénhuà, yǔyán hé xìngqù biāozhǔn xuǎnzé túshū.','Wèi yòu’ér huò értóng xiǎozǔ shuōmíng bāoróngxìng xuǎnshū de lǐyóu.']},6:{out:['Identify common types and features of nonfiction for young children.','Evaluate whether simple nonfiction information and visuals are clear and engaging.'],cn:['识别适合幼儿的常见非虚构读物类型和特征。','评价简单非虚构读物的信息和视觉内容是否清楚且有吸引力。'],py:['Shíbié shìhé yòu’ér de chángjiàn fēi xūgòu dúwù lèixíng hé tèzhēng.','Píngjià jiǎndān fēi xūgòu dúwù de xìnxī hé shìjué nèiróng shìfǒu qīngchu qiě yǒu xīyǐnlì.']},7:{out:['Explain the idea of windows, mirrors and sliding glass doors in children’s literature.','Identify stereotypes or tokenism and suggest a more inclusive book choice.'],cn:['解释儿童文学中的窗户、镜子和滑动玻璃门概念。','识别刻板印象或象征性代表，并提出更包容的选书建议。'],py:['Jiěshì értóng wénxué zhōng de chuānghù, jìngzi hé huádòng bōlí mén gàiniàn.','Shíbié kèbǎn yìnxiàng huò xiàngzhēngxìng dàibiǎo, bìng tíchū gèng bāoróng de xuǎnshū jiànyì.']},8:{out:['Describe useful features of digital books and interactive reading.','Discuss access, media guidance and censorship in age-appropriate ways.'],cn:['描述数字图书和互动阅读的实用特征。','以适合儿童年龄的方式讨论获取途径、媒体指导和审查。'],py:['Miáoshù shùzì túshū hé hùdòng yuèdú de shíyòng tèzhēng.','Yǐ shìhé értóng niánlíng de fāngshì tǎolùn huòqǔ tújìng, méitǐ zhǐdǎo hé shěnchá.']},9:{out:['Plan an expressive and interactive read-aloud for young children.','Use questions, prediction and responsive discussion during shared reading.'],cn:['为幼儿计划有表现力和互动性的朗读活动。','在共享阅读中使用提问、预测和回应式讨论。'],py:['Wèi yòu’ér jìhuà yǒu biǎoxiànlì hé hùdòngxìng de lǎngdú huódòng.','Zài gòngxiǎng yuèdú zhōng shǐyòng tíwèn, yùcè hé huíyìng shì tǎolùn.']},10:{out:['Design one literature-based extension using play, art, drama, music or language.','Explain how the extension connects children’s responses to further learning.'],cn:['设计一个使用游戏、艺术、戏剧、音乐或语言的文学延伸活动。','解释延伸活动如何把儿童的阅读回应连接到进一步学习。'],py:['Shèjì yí gè shǐyòng yóuxì, yìshù, xìjù, yīnyuè huò yǔyán de wénxué yánshēn huódòng.','Jiěshì yánshēn huódòng rúhé bǎ értóng de yuèdú huíyìng liánjiē dào jìnyíbù xuéxí.']},11:{out:['Plan ways to connect a children’s book with mathematics, science or social studies.','Explain how books can support social-emotional learning and family literacy.'],cn:['计划把儿童图书与数学、科学或社会研究联系起来的方法。','解释图书如何支持社会情感学习和家庭读写。'],py:['Jìhuà bǎ értóng túshū yǔ shùxué, kēxué huò shèhuì yánjiū liánxì qǐlái de fāngfǎ.','Jiěshì túshū rúhé zhīchí shèhuì qínggǎn xuéxí hé jiātíng dúxiě.']}};
function renderTopics(){const card=(t,i,home=false)=>`<div class="card topicCard" role="button" tabindex="0" aria-label="Topic ${i+1}: ${t[0]}" onclick="openTopic(${i})" onkeydown="if(event.key==='Enter'||event.key===' '){event.preventDefault();openTopic(${i})}"><div class="topicNo">${topicLabel(i)}</div><h3>${t[0]}<span class="cn">${t[2]}</span><span class="py">${t[3]}</span></h3><p>${t[1]}<span class="cn">${t[2]}</span><span class="py">${t[3]}</span></p>${home?'':'<span class="tag">Lesson<br>课程<br>Kèchéng</span><span class="tag">Activity<br>活动<br>Huódòng</span>'}</div>`;document.getElementById('topicGrid').innerHTML=topics.map((t,i)=>card(t,i)).join('');document.getElementById('homeTopics').innerHTML=topics.slice(0,6).map((t,i)=>card(t,i,true)).join('')}

const topic3QuizData = [{"title":"Using the Cover to Make Predictions","stem":["Before reading a picture book, a teacher asks children to examine its cover and predict what might happen in the story. One child predicts that the character is going on an adventure. What is the best teacher response?","阅读图画书之前，教师请幼儿观察封面，并预测故事中可能发生的事情。一名幼儿猜测故事中的人物即将展开一场冒险。教师怎样回应最恰当？","Yuèdú túhuàshū zhīqián, jiàoshī qǐng yòu'ér guānchá fēngmiàn, bìng yùcè gùshì zhōng kěnéng fāshēng de shìqing. Yì míng yòu'ér cāicè gùshì zhōng de rénwù jíjiāng zhǎnkāi yì chǎng màoxiǎn. Jiàoshī zěnyàng huíyìng zuì qiàdàng?"],"options":[["Ask the child to explain which cover details support the prediction and what else might happen.","请幼儿解释封面上的哪些细节支持这个预测，以及故事还可能发生什么。","Qǐng yòu'ér jiěshì fēngmiàn shàng de nǎxiē xìjié zhīchí zhège yùcè, yǐjí gùshì hái kěnéng fāshēng shénme."],["Ask the child to identify the main character and describe the character's appearance.","请幼儿指出主要人物，并描述人物的外貌。","Qǐng yòu'ér zhǐchū zhǔyào rénwù, bìng miáoshù rénwù de wàimào."],["Ask the child to connect the cover with a familiar story and explain the similarities.","请幼儿把封面与熟悉的故事联系起来，并解释两者的相似之处。","Qǐng yòu'ér bǎ fēngmiàn yǔ shúxī de gùshì liánxì qǐlái, bìng jiěshì liǎng zhě de xiāngsì zhī chù."],["Ask the child to describe the setting and explain how it might influence the events.","请幼儿描述故事背景，并解释背景可能如何影响事件的发展。","Qǐng yòu'ér miáoshù gùshì bèijǐng, bìng jiěshì bèijǐng kěnéng rúhé yǐngxiǎng shìjiàn de fāzhǎn."]],"correct":0,"explanation":["A good prediction draws on visual evidence but remains open to other possibilities. Asking children to explain their clues develops prediction, reasoning, and close observation.","合理的预测应该依据视觉证据，同时保留其他可能性。请幼儿解释线索，可以培养他们的预测能力、推理能力和仔细观察的习惯。","Hélǐ de yùcè yīnggāi yījù shìjué zhèngjù, tóngshí bǎoliú qítā kěnéngxìng. Qǐng yòu'ér jiěshì xiànsuǒ, kěyǐ péiyǎng tāmen de yùcè nénglì, tuīlǐ nénglì hé zǐxì guānchá de xíguàn."]},{"title":"Understanding the Title-Page Illustration","stem":["A picture book has a small illustration of a fox on its title page. Later, the fox becomes important to the story. What can the teacher reasonably help children understand from this early illustration?","一本图画书的扉页上有一幅狐狸的小插图。后来，狐狸成为故事中的重要角色。教师可以合理地引导幼儿从这幅早期插图中理解什么？","Yì běn túhuàshū de fēiyè shàng yǒu yì fú húli de xiǎo chātú. Hòulái, húli chéngwéi gùshì zhōng de zhòngyào juésè. Jiàoshī kěyǐ hélǐ de yǐndǎo yòu'ér cóng zhè fú zǎoqī chātú zhōng lǐjiě shénme?"],"options":[["The illustration confirms the fox's importance and reveals its role before the story begins.","这幅插图确认了狐狸的重要性，并在故事开始前揭示它的角色。","Zhè fú chātú quèrèn le húli de zhòngyàoxìng, bìng zài gùshì kāishǐ qián jiēshì tā de juésè."],["The illustration introduces a character and may encourage predictions about its role.","这幅插图介绍了一个人物，并可能引发幼儿对其角色的预测。","Zhè fú chātú jièshào le yí ge rénwù, bìng kěnéng yǐnfā yòu'ér duì qí juésè de yùcè."],["The illustration establishes the story's setting and helps children anticipate its sequence.","这幅插图建立了故事背景，并帮助幼儿预测事件的顺序。","Zhè fú chātú jiànlì le gùshì bèijǐng, bìng bāngzhù yòu'ér yùcè shìjiàn de shùnxù."],["The illustration provides background information that children need to understand the plot.","这幅插图提供了幼儿理解故事情节所需的背景信息。","Zhè fú chātú tígōng le yòu'ér lǐjiě gùshì qíngjié suǒ xū de bèijǐng xìnxī."]],"correct":1,"explanation":["A title-page illustration can introduce a character or offer an early clue, but it does not necessarily reveal the character's importance, the setting, or essential plot information. Children can use the image to make tentative predictions and revise them as they read.","扉页插图可以介绍人物或提供初步线索，但不一定会揭示人物的重要性、故事背景或关键情节。幼儿可以根据图像进行初步预测，并在阅读过程中调整自己的想法。","Fēiyè chātú kěyǐ jièshào rénwù huò tígōng chūbù xiànsuǒ, dàn bù yídìng huì jiēshì rénwù de zhòngyàoxìng, gùshì bèijǐng huò guānjiàn qíngjié. Yòu'ér kěyǐ gēnjù túxiàng jìnxíng chūbù yùcè, bìng zài yuèdú guòchéng zhōng tiáozhěng zìjǐ de xiǎngfǎ."]},{"title":"Evaluating the Double-Page Spread","stem":["In a double-page spread, a character's face and an important clue appear close to the central fold. The picture still looks attractive. What should a reviewer do before deciding that the spread is effective?","在一幅双页跨页图中，一个人物的脸和一条重要线索靠近中间的折缝。整幅图看起来仍然很美观。评价者在判断这幅跨页图是否有效之前，应该先做什么？","Zài yì fú shuāngyè kuàyè tú zhōng, yí ge rénwù de liǎn hé yì tiáo zhòngyào xiànsuǒ kàojìn zhōngjiān de zhéfèng. Zhěng fú tú kàn qǐlái réngrán hěn měiguān. Píngjià zhě zài pànduàn zhè fú kuàyè tú shìfǒu yǒuxiào zhīqián, yīnggāi xiān zuò shénme?"],"options":[["Check whether the character and clue remain visually connected across the two pages.","检查人物和线索在左右两页之间是否保持视觉上的联系。","Jiǎnchá rénwù hé xiànsuǒ zài zuǒyòu liǎng yè zhījiān shìfǒu bǎochí shìjué shàng de liánxì."],["Check whether the illustration balances the amount of text on each page.","检查插图是否与每一页的文字数量保持平衡。","Jiǎnchá chātú shìfǒu yǔ měi yì yè de wénzì shùliàng bǎochí pínghéng."],["Check whether the central fold creates a clear separation between the two scenes.","检查中间的折缝是否清楚地分隔两个场景。","Jiǎnchá zhōngjiān de zhéfèng shìfǒu qīngchu de fēngé liǎng ge chǎngjǐng."],["Check whether the main character attracts attention before the background details.","检查主要人物是否比背景细节更能吸引读者的注意。","Jiǎnchá zhǔyào rénwù shìfǒu bǐ bèijǐng xìjié gèng néng xīyǐn dúzhě de zhùyì."]],"correct":0,"explanation":["A visually attractive spread may still be difficult to read if the fold interrupts an important face, object, or visual connection. The reviewer should examine how the two pages work together and whether essential details remain clear.","即使跨页图看起来很美观，如果折缝遮挡重要的人物面部、物体或视觉联系，读者仍可能难以理解。评价者应该检查左右两页如何配合，以及重要细节是否清晰可见。","Jíshǐ kuàyè tú kàn qǐlái hěn měiguān, rúguǒ zhéfèng zhēdǎng zhòngyào de rénwù miànbù, wùtǐ huò shìjué liánxì, dúzhě réng kěnéng nányǐ lǐjiě. Píngjià zhě yīnggāi jiǎnchá zuǒyòu liǎng yè rúhé pèihé, yǐjí zhòngyào xìjié shìfǒu qīngxī kějiàn. ________________________________________"]},{"title":"Choosing Illustration Media","stem":["Two illustrators show the same scene. One uses watercolour with soft edges, while the other uses cut-paper collage with clear, sharp shapes. The story is about a child who slowly begins to feel safe after a frightening storm. What is the best way to evaluate the two illustrations?","两位插画家描绘了同一个场景。一位使用边缘柔和的水彩画，另一位使用形状清晰、边缘鲜明的剪纸拼贴画。故事讲述一个孩子在经历可怕的暴风雨后，逐渐感到安全。我们应该如何评价这两幅插画？","Liǎng wèi chāhuàjiā miáohuì le tóng yí gè chǎngjǐng. Yí wèi shǐyòng biānyuán róuhé de shuǐcǎi huà, lìng yí wèi shǐyòng xíngzhuàng qīngxī, biānyuán xiānmíng de jiǎnzhǐ pīntiē huà. Gùshì jiǎngshù yí gè háizi zài jīnglì kěpà de bàofēngyǔ hòu, zhújiàn gǎndào ānquán. Wǒmen yīnggāi rúhé píngjià zhè liǎng fú chāhuà?"],"options":[["Choose the collage because clear shapes always help young children understand a story more easily.","选择剪纸拼贴画，因为清晰的形状总是能帮助幼儿更容易地理解故事。","Xuǎnzé jiǎnzhǐ pīntiē huà, yīnwèi qīngxī de xíngzhuàng zǒng shì néng bāngzhù yòu'ér gèng róngyì de lǐjiě gùshì."],["Choose the watercolour because soft edges are the most suitable way to show a child feeling safe.","选择水彩画，因为柔和的边缘最适合表现孩子感到安全的情绪。","Xuǎnzé shuǐcǎi huà, yīnwèi róuhé de biānyuán zuì shìhé biǎoxiàn háizi gǎndào ānquán de qíngxù."],["Compare how each medium supports the story’s mood, meaning, and intended readers.","比较两种绘画媒材如何表现故事的氛围、含义以及如何适合目标读者。","Bǐjiào liǎng zhǒng huìhuà méicái rúhé biǎoxiàn gùshì de fēnwéi, hányì yǐjí rúhé shìhé mùbiāo dúzhě."],["Choose the illustration with more details because additional visual information usually improves a picture book.","选择细节较多的插画，因为更多的视觉信息通常能提升绘本的质量。","Xuǎnzé xìjié jiào duō de chāhuà, yīnwèi gèng duō de shìjué xìnxī tōngcháng néng tíshēng huìběn de zhìliàng."]],"correct":2,"explanation":["Different media create different visual effects. Watercolour may create a soft atmosphere, while collage may create strong shapes and textures. Neither medium is automatically better. The reviewer should consider how the illustrations support the story and suit its intended readers.","不同的绘画媒材会产生不同的视觉效果。水彩画可能营造柔和的氛围，而剪纸拼贴画可能呈现鲜明的形状和质感。没有一种媒材一定比较好。评价者应该考虑插画如何配合故事，以及是否适合目标读者。","Bùtóng de huìhuà méicái huì chǎnshēng bùtóng de shìjué xiàoguǒ. Shuǐcǎi huà kěnéng yíngzào róuhé de fēnwéi, ér jiǎnzhǐ pīntiē huà kěnéng chéngxiàn xiānmíng de xíngzhuàng hé zhìgǎn. Méiyǒu yì zhǒng méicái yídìng bǐjiào hǎo. Píngjiàzhě yīnggāi kǎolǜ chāhuà rúhé pèihé gùshì, yǐjí shìfǒu shìhé mùbiāo dúzhě. ________________________________________"]},{"title":"Interpreting Line and Colour","stem":["In a picture book, a child looks worried on the first day at a new school. The illustration uses crowded lines, dark blue areas, and a small figure surrounded by other children. What is the best way for a teacher to help students interpret these visual choices?","在一本绘本中，一个孩子在新学校上学的第一天显得很担心。插画使用密集的线条、深蓝色区域，并描绘一个被其他孩子围绕的小小身影。教师应该如何帮助学生理解这些视觉表现？","Zài yì běn huìběn zhōng, yí gè háizi zài xīn xuéxiào shàngxué de dì yī tiān xiǎnde hěn dānxīn. Chāhuà shǐyòng mìjí de xiàntiáo, shēn lán sè qūyù, bìng miáohuì yí gè bèi qítā háizi wéirào de xiǎoxiǎo shēnyǐng. Jiàoshī yīnggāi rúhé bāngzhù xuéshēng lǐjiě zhèxiē shìjué biǎoxiàn?"],"options":[["Ask students to focus on the child’s facial expression because it is usually the clearest clue to emotion.","请学生专注观察孩子的面部表情，因为它通常是判断情绪最清楚的线索。","Qǐng xuéshēng zhuānzhù guānchá háizi de miànbù biǎoqíng, yīnwèi tā tōngcháng shì pànduàn qíngxù zuì qīngchu de xiànsuǒ."],["Ask students to compare the colours with those in other scenes to see whether the palette changes.","请学生将这一场景的颜色与其他场景进行比较，看看色彩搭配是否有所变化。","Qǐng xuéshēng jiāng zhè yí chǎngjǐng de yánsè yǔ qítā chǎngjǐng jìnxíng bǐjiào, kànkan sècǎi dāpèi shìfǒu yǒu suǒ biànhuà."],["Interpret the dark blue areas first, then use the other visual details to confirm the mood suggested by the colour.","先解读深蓝色区域，再利用其他视觉细节确认颜色所暗示的氛围。","Xiān jiědú shēn lán sè qūyù, zài lìyòng qítā shìjué xìjié quèrèn yánsè suǒ ànshì de fēnwéi."],["Consider the colours, lines, spacing, and story context together before discussing what feelings they may suggest.","在讨论这些视觉元素可能表达的情绪之前，先综合考虑颜色、线条、空间安排和故事背景。","Zài tǎolùn zhèxiē shìjué yuánsù kěnéng biǎodá de qíngxù zhīqián, xiān zōnghé kǎolǜ yánsè, xiàntiáo, kōngjiān ānpái hé gùshì bèijǐng."]],"correct":3,"explanation":["Colour and line can help create mood, but their meanings depend on the whole illustration and the story. Crowded lines and limited space may suggest tension or discomfort in this scene. Students should support their interpretations with visual evidence rather than assume that one colour always means one emotion.","颜色和线条可以帮助营造氛围，但它们的含义取决于整幅插画和故事背景。在这个场景中，密集的线条和有限的空间可能暗示紧张或不自在。学生应该运用视觉证据支持自己的理解，而不是认定一种颜色永远代表某种情绪。","Yánsè hé xiàntiáo kěyǐ bāngzhù yíngzào fēnwéi, dàn tāmen de hányì qǔjué yú zhěng fú chāhuà hé gùshì bèijǐng. Zài zhège chǎngjǐng zhōng, mìjí de xiàntiáo hé yǒuxiàn de kōngjiān kěnéng ànshì jǐnzhāng huò bù zìzài. Xuéshēng yīnggāi yùnyòng shìjué zhèngjù zhīchí zìjǐ de lǐjiě, ér bú shì rèndìng yì zhǒng yánsè yǒngyuǎn dàibiǎo mǒu zhǒng qíngxù."]},{"title":"Understanding Composition and Scale","stem":["A double-page spread shows a small child standing near the bottom of the picture, surrounded by tall buildings and busy streets. What is the most useful question for helping children understand the composition?","一幅跨越两页的插画描绘一个小孩站在画面下方，周围是高大的建筑物和繁忙的街道。哪一个问题最能帮助孩子理解这幅画的构图？","Yì fú kuàyuè liǎng yè de chāhuà miáohuì yí gè xiǎohái zhàn zài huàmiàn xiàfāng, zhōuwéi shì gāodà de jiànzhùwù hé fánmáng de jiēdào. Nǎ yí gè wèntí zuì néng bāngzhù háizi lǐjiě zhè fú huà de gòutú?"],"options":[["Which buildings can you recognise, and what might they tell us about the city?","你能认出哪些建筑物？它们可能告诉我们关于这座城市的什么信息？","Nǐ néng rènchū nǎxiē jiànzhùwù? Tāmen kěnéng gàosu wǒmen guānyú zhè zuò chéngshì de shénme xìnxī?"],["How do the child’s size, position, and surrounding space affect the way we see the child in this setting?","孩子的大小、位置和周围空间，如何影响我们看待孩子在这个环境中的处境？","Háizi de dàxiǎo, wèizhì hé zhōuwéi kōngjiān, rúhé yǐngxiǎng wǒmen kàndài háizi zài zhège huánjìng zhōng de chǔjìng?"],["How are light and dark areas balanced across the two pages?","这两页中的明暗区域是如何取得平衡的？","Zhè liǎng yè zhōng de míng'àn qūyù shì rúhé qǔdé pínghéng de?"],["Which parts contain the most detail, and how does that help us identify the main character?","哪些部分包含最多细节？这些细节如何帮助我们辨认主角？","Nǎxiē bùfen bāohán zuì duō xìjié? Zhèxiē xìjié rúhé bāngzhù wǒmen biànrèn zhǔjué?"]],"correct":1,"explanation":["Composition includes the placement and size of objects and characters, as well as the space around them. A small child surrounded by large buildings may appear vulnerable, lonely, or overwhelmed, depending on the story. Children should use the illustration and story context together before deciding what the composition suggests.","构图包括人物和物体的位置与大小，以及它们周围的空间。一个被高大建筑物包围的小孩，可能显得脆弱、孤单或不知所措，具体含义取决于故事。孩子应该结合插画和故事背景，再判断构图可能表达什么。","Gòutú bāokuò rénwù hé wùtǐ de wèizhì yǔ dàxiǎo, yǐjí tāmen zhōuwéi de kōngjiān. Yí gè bèi gāodà jiànzhùwù bāowéi de xiǎohái, kěnéng xiǎnde cuìruò, gūdān huò bùzhī suǒcuò, jùtǐ hányì qǔjué yú gùshì. Háizi yīnggāi jiéhé chāhuà hé gùshì bèijǐng, zài pànduàn gòutú kěnéng biǎodá shénme."]},{"title":"Comparing Words and Pictures","stem":["The text in a picture book says, “What a wonderful, tidy bedroom!” However, the illustration shows toys scattered across the floor, clothes hanging from the chair, and books piled on the bed. What should a teacher encourage children to do?","绘本中的文字写道：“多么美好、整洁的卧室啊！”然而，插画却显示玩具散落在地板上，衣服挂在椅子上，书本堆在床上。教师应该鼓励孩子做什么？","Huìběn zhōng de wénzì xiě dào: “Duōme měihǎo, zhěngjié de wòshì a!” Rán’ér, chāhuà què xiǎnshì wánjù sànluò zài dìbǎn shàng, yīfu guà zài yǐzi shàng, shūběn duī zài chuáng shàng. Jiàoshī yīnggāi gǔlì háizi zuò shénme?"],"options":[["Use the written description to identify the setting and treat the illustration as extra information.","根据文字描述确定场景，并把插画当作额外的信息。","Gēnjù wénzì miáoshù quèdìng chǎngjǐng, bìng bǎ chāhuà dàngzuò éwài de xìnxī."],["Describe the objects in the illustration and practise using words about tidiness.","描述插画中的物品，并练习使用与整洁有关的词语。","Miáoshù chāhuà zhōng de wùpǐn, bìng liànxí shǐyòng yǔ zhěngjié yǒuguān de cíyǔ."],["Compare the words with the illustration and discuss how the two create different impressions.","比较文字与插画，并讨论两者如何产生不同的印象。","Bǐjiào wénzì yǔ chāhuà, bìng tǎolùn liǎng zhě rúhé chǎnshēng bùtóng de yìnxiàng."],["Decide whether the writer or the illustrator has made a mistake and explain which one is correct.","判断作者或插画家是否犯了错误，并说明哪一方才是正确的。","Pànduàn zuòzhě huò chāhuàjiā shìfǒu fàn le cuòwù, bìng shuōmíng nǎ yì fāng cái shì zhèngquè de."]],"correct":2,"explanation":["Words and pictures do not always give exactly the same impression. The contrast may be intentional and may add humour, meaning, or a new way to understand a character. Children should examine both before interpreting the scene.","文字和插画不一定总是带来完全相同的印象。这种对比可能是作者刻意安排的，也可能增加幽默感、含义，或帮助读者以新的方式理解角色。孩子应该同时观察文字和插画，再解读这个场景。","Wénzì hé chāhuà bù yídìng zǒng shì dàilái wánquán xiāngtóng de yìnxiàng. Zhè zhǒng duìbǐ kěnéng shì zuòzhě kèyì ānpái de, yě kěnéng zēngjiā yōumògǎn, hányì, huò bāngzhù dúzhě yǐ xīn de fāngshì lǐjiě juésè. Háizi yīnggāi tóngshí guānchá wénzì hé chāhuà, zài jiědú zhège chǎngjǐng."]},{"title":"Recognising Visual Irony","stem":["In a picture book, a cat hides behind a thin curtain and says, “Nobody can see me!” The illustration clearly shows the cat’s tail and feet sticking out.","在一本绘本中，一只猫躲在薄薄的窗帘后面，并说：“没有人看得见我！”插画却清楚地显示猫的尾巴和脚露在外面。","Zài yì běn huìběn zhōng, yì zhī māo duǒ zài báobáo de chuānglián hòumiàn, bìng shuō: “Méiyǒu rén kàndéjiàn wǒ!” Chāhuà què qīngchu de xiǎnshì māo de wěiba hé jiǎo lù zài wàimiàn."],"options":[["The picture gives readers a fuller view of the hiding place, allowing them to understand the situation more clearly than the words alone.","插画让读者更完整地看到藏身的地方，使他们比单看文字更清楚地理解这个情境。","Chāhuà ràng dúzhě gèng wánzhěng de kàndào cángshēn de dìfang, shǐ tāmen bǐ dān kàn wénzì gèng qīngchu de lǐjiě zhège qíngjìng."],["The contrast between the cat’s confident words and its exposed body creates suspense about whether another character will discover it.","猫自信的说法与暴露在外的身体形成对比，让读者好奇其他角色是否会发现它。","Māo zìxìn de shuōfǎ yǔ bàolù zài wài de shēntǐ xíngchéng duìbǐ, ràng dúzhě hàoqí qítā juésè shìfǒu huì fāxiàn tā."],["The mismatch between the cat’s claim and the visible evidence invites readers to recognise something the cat seems unaware of.","猫的说法与画面中可见的线索不一致，读者因此发现了猫似乎没有察觉的事情。","Māo de shuōfǎ yǔ huàmiàn zhōng kějiàn de xiànsuǒ bù yízhì, dúzhě yīncǐ fāxiàn le māo sìhū méiyǒu chájué de shìqing."],["The illustration adds a second layer of meaning by showing that the cat’s hiding strategy is ineffective, even though the cat believes it has succeeded.","插画增加了第二层含义：虽然猫以为自己藏得很好，但画面显示它的藏身方法其实没有效果。","Chāhuà zēngjiā le dì èr céng hányì: suīrán māo yǐwéi zìjǐ cáng de hěn hǎo, dàn huàmiàn xiǎnshì tā de cángshēn fāngfǎ qíshí méiyǒu xiàoguǒ."]],"correct":2,"explanation":["The humour comes from the difference between what the cat believes and what readers can see. This is visual irony because readers recognise a contradiction that the character appears not to recognise. Option D is plausible, but it focuses on the failure of the hiding strategy rather than directly identifying the reader’s awareness of the contradiction.","幽默来自猫的想法与读者所看到的情况之间的差异。这属于视觉反讽，因为读者发现了角色似乎没有察觉的矛盾。选项 D 也有道理，但它着重于藏身方法失败，而没有直接指出读者察觉到的矛盾。","Yōumò láizì māo de xiǎngfǎ yǔ dúzhě suǒ kàndào de qíngkuàng zhījiān de chāyì. Zhè shǔyú shìjué fǎnfěng, yīnwèi dúzhě fāxiàn le juésè sìhū méiyǒu chájué de máodùn. Xuǎnxiàng D yě yǒu dàolǐ, dàn tā zhuózhòng yú cángshēn fāngfǎ shībài, ér méiyǒu zhíjiē zhǐchū dúzhě chájué dào de máodùn."]},{"title":"Visual Clues and Prediction","stem":["The text says, “The little boat continued along the river.” In the illustration, the river leads towards a dark cave, and several birds are flying away from the cave. What is the best question to ask children?","文字写道：“小船继续沿着河流前进。”插画中，河流通向一个黑暗的洞穴，几只鸟正从洞穴附近飞走。教师最适合问孩子什么问题？","Wénzì xiě dào: “Xiǎo chuán jìxù yánzhe héliú qiánjìn.” Chāhuà zhōng, héliú tōngxiàng yí gè hēi’àn de dòngxué, jǐ zhī niǎo zhèng cóng dòngxué fùjìn fēi zǒu. Jiàoshī zuì shìhé wèn háizi shénme wèntí?"],"options":[["What clues can you see, and what might they suggest about what could happen next?","你看到了哪些线索？这些线索可能暗示接下来会发生什么？","Nǐ kàndào le nǎxiē xiànsuǒ? Zhèxiē xiànsuǒ kěnéng ànshì jiēxiàlái huì fāshēng shénme?"],["Which animals can you identify, and how many birds are flying away?","你能认出哪些动物？有几只鸟正在飞走？","Nǐ néng rènchū nǎxiē dòngwù? Yǒu jǐ zhī niǎo zhèngzài fēi zǒu?"],["What does the sentence tell us about the boat, and where is the river going?","这个句子告诉我们关于小船的什么信息？河流通向哪里？","Zhège jùzi gàosu wǒmen guānyú xiǎochuán de shénme xìnxī? Héliú tōngxiàng nǎlǐ?"],["What colour is the cave, and which part of the illustration looks darkest?","洞穴是什么颜色的？插画中的哪个部分看起来最暗？","Dòngxué shì shénme yánsè de? Chāhuà zhōng de nǎge bùfen kàn qǐlái zuì àn?"]],"correct":0,"explanation":["The illustration contains clues that are not stated directly in the text. The dark cave and the birds flying away may suggest danger, mystery, or an important event ahead. Children should use visual evidence to make predictions while understanding that a prediction is not a confirmed fact.","插画包含了文字没有直接说明的线索。黑暗的洞穴和飞走的鸟可能暗示危险、神秘的情况，或即将发生的重要事件。孩子应该根据视觉证据进行预测，同时明白预测并不等于已经证实的事实。","Chāhuà bāohán le wénzì méiyǒu zhíjiē shuōmíng de xiànsuǒ. Hēi’àn de dòngxué hé fēi zǒu de niǎo kěnéng ànshì wēixiǎn, shénmì de qíngkuàng, huò jíjiāng fāshēng de zhòngyào shìjiàn. Háizi yīnggāi gēnjù shìjué zhèngjù jìnxíng yùcè, tóngshí míngbai yùcè bìng bù děngyú yǐjīng zhèngshí de shìshí."]},{"title":"Discovering Meaning Through Illustrations","stem":["A picture book says, “Amir walked into the kitchen and asked for breakfast.” The illustration shows his older sister quietly putting a birthday cake behind her back while their parents exchange smiles. What can readers reasonably infer from the illustration?","一本绘本写道：“阿米尔走进厨房，要求吃早餐。”插画显示他的姐姐悄悄地把一个生日蛋糕藏到身后，而父母则相视微笑。读者可以根据插画合理地推断什么？","Yì běn huìběn xiě dào: “Āmǐ'ěr zǒu jìn chúfáng, yāoqiú chī zǎocān.” Chāhuà xiǎnshì tā de jiějie qiāoqiāo de bǎ yí gè shēngrì dàngāo cáng dào shēnhòu, ér fùmǔ zé xiāngshì wēixiào. Dúzhě kěyǐ gēnjù chāhuà hélǐ de tuīduàn shénme?"],"options":[["Amir’s sister has already told him about the birthday cake, but he is pretending not to know.","阿米尔的姐姐已经告诉他生日蛋糕的事，但他假装不知道。","Āmǐ'ěr de jiějie yǐjīng gàosu tā shēngrì dàngāo de shì, dàn tā jiǎzhuāng bù zhīdào."],["Amir’s parents are smiling because they are pleased that he has asked for breakfast.","阿米尔的父母微笑，是因为他们很高兴他要求吃早餐。","Āmǐ'ěr de fùmǔ wēixiào, shì yīnwèi tāmen hěn gāoxìng tā yāoqiú chī zǎocān."],["Amir’s sister is hiding the cake because she wants to eat it without sharing it with anyone.","阿米尔的姐姐把蛋糕藏起来，是因为她想自己吃，不愿与别人分享。","Āmǐ'ěr de jiějie bǎ dàngāo cáng qǐlái, shì yīnwèi tā xiǎng zìjǐ chī, bù yuàn yǔ biérén fēnxiǎng."],["Amir’s family may be preparing a surprise, although the illustration does not confirm exactly what will happen.","阿米尔的家人可能正在准备一个惊喜，不过插画并没有确切说明接下来会发生什么。","Āmǐ'ěr de jiārén kěnéng zhèngzài zhǔnbèi yí gè jīngxǐ, búguò chāhuà bìng méiyǒu quèqiè shuōmíng jiēxiàlái huì fāshēng shénme."]],"correct":3,"explanation":["The hidden cake and the parents’ smiles suggest that the family may be planning a surprise for Amir. However, readers cannot know the exact plan from this illustration alone. A good inference uses visual clues without treating a possibility as a confirmed fact.","被藏起来的蛋糕和父母的微笑暗示家人可能正在为阿米尔准备惊喜。然而，读者无法单凭这幅插画确定他们的具体计划。合理的推断应该根据视觉线索作出，同时不能把一种可能性当成已经证实的事实。","Bèi cáng qǐlái de dàngāo hé fùmǔ de wēixiào ànshì jiārén kěnéng zhèngzài wèi Āmǐ'ěr zhǔnbèi jīngxǐ. Rán'ér, dúzhě wúfǎ dān píng zhè fú chāhuà quèdìng tāmen de jùtǐ jìhuà. Hélǐ de tuīduàn yīnggāi gēnjù shìjué xiànsuǒ zuòchū, tóngshí bùnéng bǎ yì zhǒng kěnéngxìng dàngchéng yǐjīng zhèngshí de shìshí."]}];
function escapeTopic3Text(value){return String(value).replace(/[&<>"']/g,function(ch){return {'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[ch]})}
function renderTopic3Quiz(){
 const saved=JSON.parse(localStorage.getItem('bece_topic3_quiz_answers')||'[]');
 const attempts=Number(localStorage.getItem('bece_topic3_quiz_attempts')||'0');
 const last=localStorage.getItem('bece_topic3_quiz_score');
 let html='<section class="topic3Quiz"><h2>Student-Facing Quiz<br>学生测验<br>Xuéshēng cèyàn</h2><div class="card topic3QuizIntro"><p><b>Choose the best answer for each question.</b><br><span class="cn">为每道题选择最恰当的答案。</span><span class="py">Wèi měi dào tí xuǎnzé zuì qiàdàng de dá’àn.</span></p><p>There are 10 questions. Your answers and results are saved in this browser.<br><span class="cn">本测验共有十道题。你的答案和测验结果会保存在此浏览器中。</span><br><span class="py">Běn cèyàn gòng yǒu shí dào tí. Nǐ de dá’àn hé cèyàn jiéguǒ huì bǎocún zài cǐ liúlǎnqì zhōng.</span></p>'+(last!==null?'<p><b>Previous score: '+escapeTopic3Text(last)+'% · Attempts: '+attempts+'</b><br><span class="cn">上次分数：'+escapeTopic3Text(last)+'% · 尝试次数：'+attempts+'</span><br><span class="py">Shàng cì fēnshù: '+escapeTopic3Text(last)+'% · Chángshì cìshù: '+attempts+'</span></p>':'')+'</div>';
 html+=topic3QuizData.map(function(q,i){return '<fieldset class="topic3Question" id="topic3qcard'+i+'"><legend>'+(i+1)+'. '+escapeTopic3Text(q.stem[0])+'<span class="cn">'+escapeTopic3Text(q.stem[1])+'</span><span class="py">'+escapeTopic3Text(q.stem[2])+'</span></legend>'+q.options.map(function(o,j){return '<label class="topic3Option"><input type="radio" name="topic3q'+i+'" value="'+j+'" '+(saved[i]===j?'checked':'')+'><span class="topic3OptionText"><span>'+String.fromCharCode(65+j)+'. '+escapeTopic3Text(o[0])+'</span><span class="cn">'+escapeTopic3Text(o[1])+'</span><span class="py">'+escapeTopic3Text(o[2])+'</span></span></label>'}).join('')+'</fieldset>'}).join('');
 html+='<button class="action" onclick="gradeTopic3Quiz(false)">Check answers<br>检查答案<br>Jiǎnchá dá’àn</button> <button class="action secondary" onclick="resetTopic3Quiz()">Try again<br>重新尝试<br>Chóngxīn chángshì</button><div id="topic3QuizResult" class="result" aria-live="polite"></div></section>';
 return html;
}
function gradeTopic3Quiz(restoring){
 const answers=topic3QuizData.map(function(q,i){const e=document.querySelector('input[name="topic3q'+i+'"]:checked');return e?Number(e.value):null});
 const answered=answers.filter(v=>v!==null).length;
 const result=document.getElementById('topic3QuizResult');
 if(!restoring&&answered<topic3QuizData.length){if(result)result.innerHTML='<div class="card"><b>Please answer all 10 questions before checking.</b><br><span class="cn">请先回答全部十道题，再检查答案。</span><br><span class="py">Qǐng xiān huídá quánbù shí dào tí, zài jiǎnchá dá’àn.</span><p>Answered: '+answered+'/10<br><span class="cn">已回答：'+answered+'/10</span><br><span class="py">Yǐ huídá: '+answered+'/10</span></p></div>';return;}
 if(!restoring){localStorage.setItem('bece_topic3_quiz_answers',JSON.stringify(answers));localStorage.setItem('bece_topic3_quiz_attempts',String(Number(localStorage.getItem('bece_topic3_quiz_attempts')||'0')+1));}
 let score=0;topic3QuizData.forEach(function(q,i){if(answers[i]===q.correct)score++});const pct=Math.round(score/topic3QuizData.length*100);localStorage.setItem('bece_topic3_quiz_score',String(pct));
 const feedback=topic3QuizData.map(function(q,i){const correct=answers[i]===q.correct;const letter=String.fromCharCode(65+q.correct);const o=q.options[q.correct];return '<div class="topic3Feedback"><h4>'+(i+1)+'. '+(correct?'✓ Correct':'Review this question')+'<br><span class="cn">'+(correct?'✓ 正确':'请复习这道题')+'</span><br><span class="py">'+(correct?'Zhèngquè':'Qǐng fùxí zhè dào tí')+'</span></h4><p><b>Correct answer: '+letter+'</b><br><span class="cn">正确答案：'+letter+'</span><br><span class="py">Zhèngquè dá’àn: '+letter+'</span><br>'+escapeTopic3Text(o[0])+'<span class="cn">'+escapeTopic3Text(o[1])+'</span><span class="py">'+escapeTopic3Text(o[2])+'</span></p><p><b>Explanation</b><br>'+escapeTopic3Text(q.explanation[0])+'<span class="cn">'+escapeTopic3Text(q.explanation[1])+'</span><span class="py">'+escapeTopic3Text(q.explanation[2])+'</span></p></div>'}).join('');
 if(result)result.innerHTML='<div class="card"><h3>Score: '+score+'/10 ('+pct+'%)<br>分数：'+score+'/10（'+pct+'%）<br>Fēnshù: '+score+'/10 ('+pct+'%)</h3><p>'+(pct>=80?'Excellent work. Review the explanations to strengthen your reasoning.':pct>=60?'Good work. Read the explanations and try again if you wish.':'Keep practising. Read the explanations and try again.')+'<br><span class="cn">'+(pct>=80?'做得很好。请复习解释，进一步巩固你的推理。':pct>=60?'做得不错。阅读解释后，你可以再次尝试。':'继续练习。阅读解释后，再次尝试。')+'</span><br><span class="py">'+(pct>=80?'Zuò de hěn hǎo. Qǐng fùxí jiěshì, jìnyíbù gǒnggù nǐ de tuīlǐ.':pct>=60?'Zuò de búcuò. Yuèdú jiěshì hòu, nǐ kěyǐ zàicì chángshì.':'Jìxù liànxí. Yuèdú jiěshì hòu, zàicì chángshì.')+'</span></p><p>Answered: '+answered+'/10 · Attempt: '+Number(localStorage.getItem('bece_topic3_quiz_attempts')||'0')+'<br><span class="cn">已回答：'+answered+'/10 · 尝试次数：'+Number(localStorage.getItem('bece_topic3_quiz_attempts')||'0')+'</span><br><span class="py">Yǐ huídá: '+answered+'/10 · Chángshì cìshù: '+Number(localStorage.getItem('bece_topic3_quiz_attempts')||'0')+'</span></p></div>'+feedback;
}
function resetTopic3Quiz(){localStorage.removeItem('bece_topic3_quiz_answers');localStorage.removeItem('bece_topic3_quiz_score');openTopic3();}

function openTopic3(){showView('lesson');const h=document.getElementById('lessonContent');h.innerHTML=`
<div class="lessonTitle"><div class="eyebrow">TOPIC 3<br>主题三<br>Zhǔtí Sān</div><h1>The Art of the Picture Book</h1><div class="uiTri"><div class="cn">图画书的艺术</div><div class="py">Túhuà shū de yìshù</div></div><p class="lead">Explore how the words, design and illustrations of a picture book work together to create meaning.<br><span class="cn">探索图画书中的文字、设计和插图如何相互配合，共同创造意义。</span><br><span class="py">Tànsuǒ túhuà shū zhōng de wénzì, shèjì hé chātú rúhé xiānghù pèihé, gòngtóng chuàngzào yìyì.</span></p></div>
<h2>Learning Outcomes<br>学习成果<br>Xuéxí chéngguǒ</h2>
${tri('Identify common paratext and visual features.','识别常见的副文本和视觉特征。','Shíbié chángjiàn de fù wénběn hé shìjué tèzhēng.')}
${tri('Explain how illustrations add meaning beyond the words.','解释插图如何在文字之外增加意义。','Jiěshì chātú rúhé zài wénzì zhīwài zēngjiā yìyì.')}
<h2>3.1 Paratext, Peritext and Double-Page Spreads<br>副文本、书内副文本与跨页<br>Fù wénběn, shū nèi fù wénběn yǔ kuāyè</h2>
${tri('Paratext includes the features around a book’s main story, such as its cover, title and other framing elements. These features shape readers’ expectations.','副文本包括围绕图书主要故事的元素，例如封面、书名及其他框架元素。这些元素会影响读者的期待。','Fù wénběn bāokuò wéirào túshū zhǔyào gùshi de yuánsù, lìrú fēngmiàn, shūmíng jí qítā kuàngjià yuánsù. Zhèxiē yuánsù huì yǐngxiǎng dúzhě de qīdài.')}
${tri('Peritext refers to elements physically included in the book, such as the cover, endpapers, title page and dedication. Look at what they tell readers before the story begins.','书内副文本指书中实际包含的元素，例如封面、环衬、扉页和献词。留意这些元素在故事开始前向读者传达了什么。','Shū nèi fù wénběn zhǐ shū zhōng shíjì bāohán de yuánsù, lìrú fēngmiàn, huánchèn, fēiyè hé xiàncí. Liúyì zhèxiē yuánsù zài gùshi kāishǐ qián xiàng dúzhě chuándále shénme.')}
${tri('A double-page spread is the two facing pages viewed together. The arrangement can guide the eye, create a sense of space, or reveal an important moment.','跨页是指一起观看的左右两页。页面安排可以引导视线、营造空间感，或呈现重要时刻。','Kuāyè shì zhǐ yìqǐ guānkàn de zuǒyòu liǎng yè. Yèmiàn ānpái kěyǐ yǐndǎo shìxiàn, yíngzào kōngjiān gǎn, huò chéngxiàn zhòngyào shíkè.')}
<h2>3.2 Illustration Media, Style and Visual Choices<br>插图媒介、风格与视觉选择<br>Chātú méijiè, fēnggé yǔ shìjué xuǎnzé</h2>
${tri('Illustrations may be made with paint, pencil, collage, printmaking, photography or digital tools. The medium affects texture, detail and mood.','插图可以使用颜料、铅笔、拼贴、版画、摄影或数码工具创作。不同媒介会影响质感、细节和气氛。','Chātú kěyǐ shǐyòng yánliào, qiānbǐ, pīntiē, bǎnhuà, shèyǐng huò shùmǎ gōngjù chuàngzuò. Bùtóng méijiè huì yǐngxiǎng zhìgǎn, xìjié hé qìfēn.')}
${tri('Line can suggest movement, energy or calm. Colour can create mood and draw attention. Composition—the arrangement of visual elements—guides what readers notice first.','线条可以表现动作、活力或平静。色彩可以营造气氛并吸引注意。构图是视觉元素的安排，它会引导读者先注意哪些内容。','Xiàntiáo kěyǐ biǎoxiàn dòngzuò, huólì huò píngjìng. Sècǎi kěyǐ yíngzào qìfēn bìng xīyǐn zhùyì. Gòutú shì shìjué yuánsù de ānpái, tā huì yǐndǎo dúzhě xiān zhùyì nǎxiē nèiróng.')}
${tri('Illustration style includes the artist’s choices about shape, detail, realism, exaggeration and viewpoint. Ask how these choices influence the reader’s response.','插图风格包括艺术家对形状、细节、写实程度、夸张手法和视角的选择。思考这些选择如何影响读者的反应。','Chātú fēnggé bāokuò yìshùjiā duì xíngzhuàng, xìjié, xiěshí chéngdù, kuāzhāng shǒufǎ hé shìjiǎo de xuǎnzé. Sīkǎo zhèxiē xuǎnzé rúhé yǐngxiǎng dúzhě de fǎnyìng.')}
<h2>3.3 How Pictures Tell Stories: Counterpoint and Irony<br>图画如何讲故事：反衬与反讽<br>Túhuà rúhé jiǎng gùshi: fǎnchèn yǔ fǎnfěng</h2>
${tri('Words and pictures do not always give exactly the same information. Sometimes the pictures add details that the words do not mention.','文字和图画不一定传达完全相同的信息。有时，图画会补充文字没有提到的细节。','Wénzì hé túhuà bù yídìng chuándá wánquán xiāngtóng de xìnxī. Yǒushí, túhuà huì bǔchōng wénzì méiyǒu tídào de xìjié.')}
${tri('Counterpoint occurs when words and pictures work in different or contrasting ways, creating a fuller meaning when readers consider both.','当文字和图画以不同或对比的方式发挥作用时，就形成反衬；读者结合两者理解，便能发现更完整的意义。','Dāng wénzì hé túhuà yǐ bùtóng huò duìbǐ de fāngshì fāhuī zuòyòng shí, jiù xíngchéng fǎnchèn; dúzhě jiéhé liǎngzhě lǐjiě, biàn néng fāxiàn gèng wánzhěng de yìyì.')}
${tri('Visual irony happens when the illustration shows something different from, or more revealing than, what a character says or believes. Readers may notice information the character has missed.','当插图呈现的内容与角色所说或所相信的不同，或揭示更多信息时，就可能产生视觉反讽。读者可能会发现角色没有注意到的事情。','Dāng chātú chéngxiàn de nèiróng yǔ juésè suǒ shuō huò suǒ xiāngxìn de bùtóng, huò jiēshì gèng duō xìnxī shí, jiù kěnéng chǎnshēng shìjué fǎnfěng. Dúzhě kěnéng huì fāxiàn juésè méiyǒu zhùyì dào de shìqing.')}
<h2>Hands-on Activity<br>动手活动<br>Dòngshǒu huódòng</h2>
<div class="activity"><b>Picture-Book Detective<br>图画书侦探<br>Túhuà shū zhēntàn</b><p>Choose one picture book and examine a double-page spread. Identify one design or peritext feature, one visual choice (line, colour or composition), and one detail that adds meaning beyond the words.</p><p>选择一本图画书，仔细观察其中一个跨页。找出一个设计或书内副文本元素、一项视觉选择（线条、色彩或构图），以及一个在文字之外增加意义的细节。</p><p class="muted">Xuǎnzé yì běn túhuà shū, zǐxì guānchá qízhōng yí gè kuāyè. Zhǎochū yí gè shèjì huò shū nèi fù wénběn yuánsù, yí xiàng shìjué xuǎnzé (xiàntiáo, sècǎi huò gòutú), yǐjí yí gè zài wénzì zhīwài zēngjiā yìyì de xìjié.</p><label for="topic3Reflection"><b>Reflection<br>反思<br>Fǎnsī</b></label><p>How might the meaning change if the illustrations were different?<br>如果插图不同，故事的意义可能会怎样改变？<br>Rúguǒ chātú bùtóng, gùshi de yìyì kěnéng huì zěnyàng gǎibiàn?</p><textarea id="topic3Reflection" rows="4" style="width:100%;padding:12px;border:1px solid var(--border);border-radius:10px;background:var(--surface);color:var(--text)" placeholder="Write a short reflection...&#10;写下简短的反思……&#10;Xiě xià jiǎnduǎn de fǎnsī……"></textarea><button class="action" onclick="localStorage.setItem('bece_topic3_reflection',document.getElementById('topic3Reflection').value);document.getElementById('topic3Save').textContent='Saved / 已保存 / Yǐ bǎocún'">Save reflection<br>保存反思<br>Bǎocún fǎnsī</button> <span id="topic3Save" class="muted statusLive"></span></div>
${renderTopic3Quiz()}
<button class="action" onclick="completeTopic(2)">Mark learning content complete<br>标记学习内容已完成<br>Biāojì xuéxí nèiróng yǐ wánchéng</button>
`;
let saved=localStorage.getItem('bece_topic3_reflection');if(saved!==null)document.getElementById('topic3Reflection').value=saved;if(localStorage.getItem('bece_topic3_quiz_score')!==null)gradeTopic3Quiz(true);}
function openTopic(i){if(i===2){openTopic3();return;}showView('lesson');const t=topics[i],d=lessonData[i];let outcomes=d?.out||['Describe key ideas from this topic.','Use the ideas in a practical early childhood literature activity.'];let cn=d?.cn||['描述本主题的主要概念。','在幼儿文学活动中运用这些概念。'];let py=d?.py||['Miáoshù běn zhǔtí de zhǔyào gàiniàn.','Zài yòu’ér wénxué huódòng zhōng yùnyòng zhèxiē gàiniàn.'];document.getElementById('lessonContent').innerHTML=`<div class="lessonTitle"><div class="eyebrow">${topicLabel(i)}</div><h1>${t[0]}</h1><div class="uiTri"><div class="cn">${t[2]}</div><div class="py">${t[3]}</div></div><p class="lead">${t[1]}<br><span class="cn">${t[2]}</span><br><span class="py">${t[3]}</span></p></div><h2>${lessonUi.out[0]}<br>${lessonUi.out[1]}<br>${lessonUi.out[2]}</h2>${outcomes.map((x,j)=>tri(x,cn[j],py[j])).join('')}<h2>${lessonUi.ideas[0]}<br>${lessonUi.ideas[1]}<br>${lessonUi.ideas[2]}</h2>${tri('Look at quality, purpose and the child.','关注质量、目的和儿童。','Guānzhù zhìliàng, mùdì hé értóng.')}${tri('Connect books with children’s development, interests and experiences.','把图书与儿童的发展、兴趣和经验联系起来。','Bǎ túshū yǔ értóng de fāzhǎn, xìngqù hé jīngyàn liánxì qǐlái.') }<h2>${lessonUi.try[0]}<br>${lessonUi.try[1]}<br>${lessonUi.try[2]}</h2><div class="activity"><b>${lessonUi.detective[0]}<br>${lessonUi.detective[1]}<br>${lessonUi.detective[2]}</b><p>Choose one children’s book. In pairs, find one strength in the words, one strength in the illustrations, and one way the book can support children’s learning.</p><p>选择一本儿童读物。两人一组，找出文字的一个优点、插图的一个优点，以及这本书如何支持儿童学习。</p><p class="muted">Xuǎnzé yì běn értóng dúwù. Liǎng rén yì zǔ, zhǎochū wénzì de yí gè yōudiǎn, chātú de yí gè yōudiǎn, yǐjí zhè běn shū rúhé zhīchí értóng xuéxí.</p><button class="action" onclick="completeTopic(${i})">${lessonUi.complete[0]}<br>${lessonUi.complete[1]}<br>${lessonUi.complete[2]}</button></div><h2>${lessonUi.reflection[0]}<br>${lessonUi.reflection[1]}<br>${lessonUi.reflection[2]}</h2><p>How would you adapt this idea for a child with a different language, ability or learning need?<br>如果儿童有不同的语言、能力或学习需要，你会如何调整这个想法？<br>Rúguǒ értóng yǒu bùtóng de yǔyán, nénglì huò xuéxí xūyào, nǐ huì rúhé tiáozhěng zhège xiǎngfǎ?</p><textarea rows="4" style="width:100%;padding:12px;border:1px solid var(--border);border-radius:10px;background:var(--surface2);color:var(--text)" placeholder="Write a short reflection...&#10;写下简短的反思……&#10;Xiě xià jiǎnduǎn de fǎnsī……"></textarea>`}
function completeTopic(i){let done=JSON.parse(localStorage.getItem('bece_done')||'[]');if(!done.includes(i))done.push(i);done.sort((a,b)=>a-b);localStorage.setItem('bece_done',JSON.stringify(done));syncAllProgress();alert('Topic marked complete.\n主题已标记为完成。\nZhǔtí yǐ biāojì wéi wánchéng.');}
function continueLearning(){let done=JSON.parse(localStorage.getItem('bece_done')||'[]');let next=topics.findIndex((_,i)=>!done.includes(i));openTopic(next<0?0:next)}
function syncAllProgress(){let done=JSON.parse(localStorage.getItem('bece_done')||'[]');let pct=Math.round(done.length/12*100);let pt=document.getElementById('progressText'),pb=document.getElementById('progressBar'),pc=pb?.parentElement,dc=document.getElementById('doneCount');if(pt)pt.textContent=pct+'%';if(pb)pb.style.width=pct+'%';if(pc){pc.setAttribute('aria-valuenow',pct);pc.setAttribute('aria-label','Course progress / 课程进度 / Kèchéng jìndù')}if(dc)dc.textContent=done.length;let dt=document.getElementById('dashTopics'),ds=document.getElementById('dashTopicStatus'),de=document.getElementById('dashTopicEvidence');if(dt)dt.textContent=done.length+'/12';if(ds)ds.innerHTML=done.length===12?'Complete<br>已完成<br>Yǐ wánchéng':'In progress<br>进行中<br>Jìnxíng zhōng';if(de)de.innerHTML=done.length+'/12 completed<br>'+done.length+'/12 已完成<br>'+done.length+'/12 yǐ wánchéng';let next=topics.findIndex((_,i)=>!done.includes(i)),ct=document.getElementById('continueText'),cb=document.getElementById('continueBtn');if(next<0){if(ct)ct.innerHTML='All topics completed. Review or practise again.<br>所有主题已完成。你可以复习或再次练习。<br>Suǒyǒu zhǔtí yǐ wánchéng. Nǐ kěyǐ fùxí huò zàicì liànxí.';if(cb)cb.innerHTML='Review Topic 1<br>复习主题1<br>Fùxí zhǔtí 1'}else{if(ct)ct.innerHTML='Continue with Topic '+(next+1)+': '+topics[next][0]+'<br>继续学习主题'+(next+1)+'：'+topics[next][2]+'<br>Jìxù xuéxí zhǔtí '+(next+1)+'：'+topics[next][3];if(cb)cb.innerHTML='Continue learning<br>继续学习<br>Jìxù xuéxí'}let q=localStorage.getItem('bece_quiz');let qs=document.getElementById('quizScore'),dq=document.getElementById('dashQuiz'),dqt=document.getElementById('dashQuizTop');if(q){if(qs)qs.textContent=q+'%';if(dq)dq.innerHTML=q+'%<br>已完成<br>Yǐ wánchéng';if(dqt)dqt.textContent=q+'%'}else{if(qs)qs.textContent='—';if(dq)dq.innerHTML='Not attempted<br>未尝试<br>Wèi chángshì';if(dqt)dqt.textContent='—'}let ca1=JSON.parse(localStorage.getItem('bece_ca1')||'null'),port=document.getElementById('dashPort'),cat=document.getElementById('dashCA1Top');if(ca1?.status==='Ready for lecturer review'){if(port)port.innerHTML='Ready for review<br>准备查看<br>Zhǔnbèi chákàn';if(cat)cat.textContent='Ready for review'}else if(ca1){if(port)port.innerHTML='Started<br>已开始<br>Yǐ kāishǐ';if(cat)cat.textContent='Started'}else{if(port)port.innerHTML='Not started<br>未开始<br>Wèi kāishǐ';if(cat)cat.textContent='Not started'}}
function updateProgress(){syncAllProgress()}
const tools=[['Book Selection Checklist','Check age fit, language, illustrations, representation and learning value.','检查年龄适配、语言、插图、代表性和学习价值。','Jiǎnchá niánlíng shìpèi, yǔyán, chātú, dàibiǎoxìng hé xuéxí jiàzhí.'],['Read-Aloud Planner','Plan before-reading, during-reading and after-reading prompts.','计划阅读前、阅读中和阅读后的提示。','Jìhuà yuèdú qián, yuèdú zhōng hé yuèdú hòu de tíshì.'],['Literature Activity Bank','Ideas for drama, art, music, movement, play and discussion.','戏剧、艺术、音乐、动作、游戏和讨论活动的想法。','Xìjù, yìshù, yīnyuè, dòngzuò, yóuxì hé tǎolùn huódòng de xiǎngfǎ.'],['Inclusive Book Review','Use windows, mirrors, sliding doors and representation questions.','使用窗户、镜子、滑动玻璃门和代表性问题。','Shǐyòng chuānghù, jìngzi, huádòng bōlí mén hé dàibiǎoxìng wèntí.']];function renderTools(){var html='';tools.forEach(function(x,i){html+='<div class="toolItem"><h3>'+x[0]+'<br><span class="cn">'+x[2]+'</span><br><span class="py">'+x[3]+'</span></h3><p class="muted">'+x[1]+'<br>'+x[2]+'<br>'+x[3]+'</p><button class="action secondary" onclick="openTool('+i+')">Open template<br>打开模板<br>Dǎkāi múbǎn</button></div>'});html+='<div id="toolPanel"></div>';document.getElementById('toolGrid').innerHTML=html}
function closeTool(){document.getElementById('toolPanel').innerHTML=''}
function openTool(i){var p=document.getElementById('toolPanel');var t=[['Book Selection Checklist','图书选择检查表','Túshū xuǎnzé jiǎnchábiǎo'],['Read-Aloud Planner','朗读计划表','Lǎngdú jìhuàbiǎo'],['Literature Activity Bank','文学活动库','Wénxué huódòngkù'],['Inclusive Book Review','包容性图书评价','Bāoróngxìng túshū píngjià']][i];var h='<div class="toolPanel"><h3>'+t[0]+'<br>'+t[1]+'<br><span class="muted">'+t[2]+'</span></h3><button class="back" onclick="closeTool()">Close / 关闭 / Guānbì</button>';if(i===0)h+='<div class="toolFields"><input id="bookName" placeholder="Book title / 图书名称 / Túshū míngchēng"><div class="checkRow"><input type="checkbox"><span>Age and developmental fit<br>年龄和发展适配<br>Niánlíng hé fāzhǎn shìpèi</span></div><div class="checkRow"><input type="checkbox"><span>Literary and artistic quality<br>文学与艺术质量<br>Wénxué yǔ yìshù zhìliàng</span></div><div class="checkRow"><input type="checkbox"><span>Clear language and engaging illustrations<br>清晰的语言和有吸引力的插图<br>Qīngxī de yǔyán hé yǒu xīyǐnlì de chātú</span></div><div class="checkRow"><input type="checkbox"><span>Inclusive and respectful representation<br>包容和尊重的代表性<br>Bāoróng hé zūnzhòng de dàibiǎoxìng</span></div><textarea id="bookNote" rows="3" placeholder="Why choose this book? / 为什么选择这本书？ / Wèishéme xuǎnzé zhè běn shū?"></textarea><button class="action" onclick="saveTool(0)">Save checklist<br>保存检查表<br>Bǎocún jiǎnchábiǎo</button></div>';else if(i===1)h+='<div class="toolFields"><input id="raTitle" placeholder="Book title / 图书名称 / Túshū míngchēng"><input id="raAge" placeholder="Age group / 年龄组 / Niánlíng zǔ"><textarea id="raBefore" rows="3" placeholder="Before reading / 阅读前 / Yuèdú qián"></textarea><textarea id="raDuring" rows="3" placeholder="During reading / 阅读中 / Yuèdú zhōng"></textarea><textarea id="raAfter" rows="3" placeholder="After reading / 阅读后 / Yuèdú hòu"></textarea><button class="action" onclick="saveTool(1)">Save planner<br>保存计划<br>Bǎocún jìhuà</button></div>';else if(i===2)h+='<ul class="toolList"><li>Drama: act out a character’s feelings.<br>戏剧：表演角色的感受。<br>Xìjù: biǎoyǎn juésè de gǎnshòu.</li><li>Art: draw a new ending or favourite scene.<br>艺术：画一个新结局或最喜欢的场景。<br>Yìshù: huà yí gè xīn jiéjú huò zuì xǐhuān de chǎngjǐng.</li><li>Music and rhyme: add a beat, action or repeated line.<br>音乐和押韵：加入节拍、动作或重复句。<br>Yīnyuè hé yāyùn: jiārù jiépāi, dòngzuò huò chóngfù jù.</li><li>Movement: move like a character or animal.<br>动作：模仿角色或动物移动。<br>Dòngzuò: mófǎng juésè huò dòngwù yídòng.</li><li>Math and science: count, sort, compare or investigate something from the book.<br>数学和科学：数数、分类、比较或探究图书中的内容。<br>Shùxué hé kēxué: shǔshù, fēnlèi, bǐjiào huò tànjiū túshū zhōng de nèiróng.</li></ul><textarea id="activityNote" rows="4" placeholder="Your activity idea / 你的活动想法 / Nǐ de huódòng xiǎngfǎ"></textarea><button class="action" onclick="saveTool(2)">Save activity<br>保存活动<br>Bǎocún huódòng</button>';else h+='<div class="toolFields"><input id="incTitle" placeholder="Book title / 图书名称 / Túshū míngchēng"><div class="checkRow"><input type="checkbox"><span>Mirror: can children see themselves respectfully?<br>镜子：儿童能以被尊重的方式看到自己吗？<br>Jìngzi: értóng néng yǐ bèi zūnzhòng de fāngshì kàndào zìjǐ ma?</span></div><div class="checkRow"><input type="checkbox"><span>Window: does the book help children learn about others?<br>窗户：这本书帮助儿童了解他人吗？<br>Chuānghù: zhè běn shū bāngzhù értóng liǎojiě tārén ma?</span></div><div class="checkRow"><input type="checkbox"><span>Sliding glass door: does it invite another experience?<br>滑动玻璃门：它邀请儿童进入另一种经验吗？<br>Huádòng bōlí mén: tā yāoqǐng értóng jìnrù lìng yì zhǒng jīngyàn ma?</span></div><div class="checkRow"><input type="checkbox"><span>Check for stereotypes or tokenism.<br>检查是否有刻板印象或象征性代表。<br>Jiǎnchá shìfǒu yǒu kèbǎn yìnxiàng huò xiàngzhēngxìng dàibiǎo.</span></div><textarea id="incNote" rows="4" placeholder="What could be improved? / 可以改进什么？ / Kěyǐ gǎijìn shénme?"></textarea><button class="action" onclick="saveTool(3)">Save review<br>保存评价<br>Bǎocún píngjià</button></div>';p.innerHTML=h+'</div>';loadTool(i)}
function saveTool(i){var ids=[['bookName','bookNote'],['raTitle','raAge','raBefore','raDuring','raAfter'],['activityNote'],['incTitle','incNote']][i],data=[];ids.forEach(function(id){var e=document.getElementById(id);data.push([id,e?e.value:''])});localStorage.setItem('bece_tool_'+i,JSON.stringify(data));alert('Saved.\n已保存。\nYǐ bǎocún.')}
function loadTool(i){var data=JSON.parse(localStorage.getItem('bece_tool_'+i)||'[]');data.forEach(function(a){var e=document.getElementById(a[0]);if(e)e.value=a[1]})}
const questions=[
['Which statement best describes quality children’s literature?','哪一项最能描述优质儿童文学？','Nǎ yí xiàng zuì néng miáoshù yōuzhì értóng wénxué?',['It only teaches facts<br>它只教授事实<br>Tā zhǐ jiàoshòu shìshí','It combines meaningful content with artistic and developmental quality<br>它结合有意义的内容、艺术质量和发展适宜性<br>Tā jiéhé yǒu yìyì de nèiróng, yìshù zhìliàng hé fāzhǎn shìyíxìng','It must always be a long book<br>它必须总是一本长书<br>Tā bìxū zǒng shì yì běn cháng shū'],1,'Quality considers the whole book and the child.'], 
['A quality picture book should be judged only by its story.','优质图画书只应该根据故事来评价。','Yōuzhì túhuàshū zhǐ yīnggāi gēnjù gùshì lái píngjià.',['True<br>正确<br>Zhèngquè','False<br>错误<br>Cuòwù'],1,'Text, images, design and developmental fit all matter.'],
['Which feature helps children understand a book’s design and meaning?','哪一个特征帮助儿童理解图书的设计和意义？','Nǎ yí gè tèzhēng bāngzhù értóng lǐjiě túshū de shèjì hé yìyì?',['Paratext and visual design<br>副文本和视觉设计<br>Fù wénběn hé shìjué shèjì','Only the page number<br>只有页码<br>Zhǐyǒu yèmǎ','Only the price<br>只有价格<br>Zhǐyǒu jiàgé'],0,'Paratext and visual choices can add meaning around the main story.'],
['Which format is especially useful for very young children because it is sturdy?','哪一种形式特别适合幼儿，因为它比较结实？','Nǎ yì zhǒng xíngshì tèbié shìhé yòu’ér, yīnwèi tā bǐjiào jiēshi?',['Board book<br>纸板书<br>Zhǐbǎnshū','Long novel<br>长篇小说<br>Chángpiān xiǎoshuō','Dictionary only<br>只有词典<br>Zhǐyǒu cídiǎn'],0,'Board books are durable and suitable for early exploration.'],
['What helps make poetry enjoyable for young children?','什么能帮助幼儿享受诗歌？','Shénme néng bāngzhù yòu’ér xiǎngshòu shīgē?',['Rhythm, rhyme and sound<br>节奏、押韵和声音<br>Jiézòu, yāyùn hé shēngyīn','Long explanations only<br>只有长篇解释<br>Zhǐyǒu chángpiān jiěshì','Silent reading only<br>只有默读<br>Zhǐyǒu mòdú'],0,'Sound patterns make poetry memorable, playful and enjoyable.'],
['When selecting a book, a teacher should consider…','选择图书时，教师应该考虑……','Xuǎnzé túshū shí, jiàoshī yīnggāi kǎolǜ……',['Only the teacher’s favourite book<br>只有教师最喜欢的书<br>Zhǐyǒu jiàoshī zuì xǐhuān de shū','Children’s development, interests, language and culture<br>儿童的发展、兴趣、语言和文化<br>Értóng de fāzhǎn, xìngqù, yǔyán hé wénhuà','Only the cover colour<br>只有封面的颜色<br>Zhǐyǒu fēngmiàn de yánsè'],1,'Book selection should fit the children and context.'],
['Which is a useful feature of nonfiction for young children?','哪一项是适合幼儿的非虚构读物的有用特征？','Nǎ yí xiàng shì shìhé yòu’ér de fēi xūgòu dúwù de yǒuyòng tèzhēng?',['Clear information supported by useful visuals<br>由有用视觉内容支持的清晰信息<br>Yóu yǒuyòng shìjué nèiróng zhīchí de qīngxī xìnxī','Confusing facts and tiny text<br>混乱的事实和很小的文字<br>Hùnluàn de shìshí hé hěn xiǎo de wénzì','No connection to children’s questions<br>与儿童的问题没有联系<br>Yǔ értóng de wèntí méiyǒu liánxì'],0,'Good nonfiction presents information clearly and invites curiosity.'],
['A “mirror” book can help a child…','“镜子”类图书可以帮助儿童……','“Jìngzi” lèi túshū kěyǐ bāngzhù értóng……',['See their own experiences represented<br>看到自己的经验被呈现<br>Kàndào zìjǐ de jīngyàn bèi chéngxiàn','Avoid learning about others<br>避免了解他人<br>Bìmiǎn liǎojiě tārén','Ignore differences<br>忽略差异<br>Hūlüè chāyì'],0,'Mirrors reflect children’s identities, experiences or lives.'],
['A good digital children’s book should…','一本好的数字儿童读物应该……','Yì běn hǎo de shùzì értóng dúwù yīnggāi……',['Use every interactive feature possible<br>使用所有可能的互动功能<br>Shǐyòng suǒyǒu kěnéng de hùdòng gōngnéng','Support reading without unnecessary distraction<br>支持阅读，并避免不必要的干扰<br>Zhīchí yuèdú, bìng bìmiǎn bù bìyào de gānrǎo','Replace all adult interaction<br>取代所有成人互动<br>Qǔdài suǒyǒu chéngrén hùdòng'],1,'Digital features should support, not distract from, meaningful reading.'],
['A read-aloud is strongest when the teacher…','朗读活动在教师……时最有效。','Lǎngdú huódòng zài jiàoshī……shí zuì yǒuxiào.',['Reads as fast as possible<br>尽可能快速朗读<br>Jǐn kěnéng kuàisù lǎngdú','Invites interaction and responds to children<br>邀请互动并回应儿童<br>Yāoqǐng hùdòng bìng huíyìng értóng','Avoids questions<br>避免提问<br>Bìmiǎn tíwèn'],1,'Interactive reading gives children opportunities to think, respond and predict.'],
['Which is a good literature-based extension?','哪一项是好的文学延伸活动？','Nǎ yí xiàng shì hǎo de wénxué yánshēn huódòng?',['Copy the whole story<br>抄写整个故事<br>Chāoxiě zhěnggè gùshì','Act, draw, move, sing or investigate ideas from the book<br>表演、绘画、动作、歌唱或探究图书中的想法<br>Biǎoyǎn, huìhuà, dòngzuò, gēchàng huò tànjiū túshū zhōng de xiǎngfǎ','Stop children from discussing the story<br>阻止儿童讨论故事<br>Zǔzhǐ értóng tǎolùn gùshì'],1,'Extensions help children respond creatively and connect reading to further learning.'],
['A book can support mathematics, science or social studies when the teacher…','当教师……时，图书可以支持数学、科学或社会研究。','Dāng jiàoshī……shí, túshū kěyǐ zhīchí shùxué, kēxué huò shèhuì yánjiū.',['Connects the story with meaningful questions and activities<br>把故事与有意义的问题和活动联系起来<br>Bǎ gùshì yǔ yǒu yìyì de wèntí hé huódòng liánxì qǐlái','Uses the book only as decoration<br>只把图书当作装饰<br>Zhǐ bǎ túshū dàngzuò zhuāngshì','Avoids children’s questions<br>避免儿童提问<br>Bìmiǎn értóng tíwèn'],0,'Cross-curricular learning works best when the book leads to purposeful exploration.']
];
function renderQuiz(){let saved=JSON.parse(localStorage.getItem('bece_quiz_answers')||'[]');document.getElementById('quizBox').innerHTML='<div class="card"><b>12 questions • One question from each topic<br>12道题 • 每个主题一道题<br>12 dào tí • Měi gè zhǔtí yí dào tí</b><p class="muted">Select one answer for each question. Your score is saved in this browser.<br>每道题选择一个答案。你的分数会保存在此浏览器中。<br>Měi dào tí xuǎnzé yí gè dá’àn. Nǐ de fēnshù huì bǎocún zài cǐ liúlǎnqì zhōng.</p></div>'+questions.map((q,i)=>'<div class="quizQ"><b>'+ (i+1)+'. '+q[0]+'</b><div class="muted">'+q[1]+'<br>'+q[2]+'</div>'+q[3].map((a,j)=>'<label><input type="radio" name="q'+i+'" value="'+j+'" '+(saved[i]===j?'checked':'')+'> <span class="uiTri">'+a+'</span></label>').join('')+'</div>').join('')+'<button class="action" onclick="gradeQuiz()">Check answers<br>检查答案<br>Jiǎnchá dá’àn</button> <button class="action secondary" onclick="resetQuiz()">Reset quiz<br>重新测验<br>Chóngxīn cèyàn</button><div id="quizResult" class="result"></div>'}
function gradeQuiz(){let s=0,answered=0,answers=[];questions.forEach((q,i)=>{let v=document.querySelector('input[name=q'+i+']:checked');let a=v?+v.value:-1;answers.push(a);if(a>-1)answered++;if(a===q[4])s++});let pct=Math.round(s/questions.length*100);let attempts=Number(localStorage.getItem('bece_quiz_attempts')||0)+1;localStorage.setItem('bece_quiz',pct);localStorage.setItem('bece_quiz_answers',JSON.stringify(answers));localStorage.setItem('bece_quiz_attempts',attempts);let msg=pct>=80?'Excellent! Keep applying the ideas in practice.':pct>=60?'Good work. Review the explanations and try again if you wish.':'Keep practising. Review the key ideas and try the quiz again.';let cn=pct>=80?'很好！继续把这些概念应用到实践中。':pct>=60?'做得不错。复习解释后，你可以再次尝试。':'继续练习。复习主要概念后，再次尝试测验。';let py=pct>=80?'Hěn hǎo! Jìxù bǎ zhèxiē gàiniàn yìngyòng dào shíjiàn zhōng.':pct>=60?'Zuò de búcuò. Fùxí jiěshì hòu, nǐ kěyǐ zàicì chángshì.':'Jìxù liànxí. Fùxí zhǔyào gàiniàn hòu, zàicì chángshì cèyàn.';let detail=questions.map((q,i)=>'<div class="tri"><b>'+((answers[i]===q[4])?'✓ Correct / 正确 / Zhèngquè':'✗ Review / 需要复习 / Xūyào fùxí')+'</b><br>'+q[5]+'</div>').join('');document.getElementById('quizResult').innerHTML='<div class="card"><strong>Score: '+s+'/'+questions.length+' ('+pct+'%)</strong><br>分数：'+s+'/'+questions.length+'（'+pct+'%）<br>Fēnshù: '+s+'/'+questions.length+' ('+pct+'%)<p>'+msg+'<br>'+cn+'<br>'+py+'</p><p class="muted">Answered: '+answered+'/'+questions.length+' • Attempt '+attempts+'<br>已回答：'+answered+'/'+questions.length+' • 第'+attempts+'次尝试<br>Yǐ huídá: '+answered+'/'+questions.length+' • Dì '+attempts+' cì chángshì</p>'+detail+'</div>';document.getElementById('quizScore').textContent=pct+'%';document.getElementById('dashQuiz').innerHTML=pct+'%<br>已完成<br>Yǐ wánchéng';document.getElementById('dashQuizTop').textContent=pct+'%';}
function resetQuiz(){localStorage.removeItem('bece_quiz_answers');renderQuiz();document.getElementById('quizResult').innerHTML=''}
function saveReflection(){let data={title:document.getElementById('ca1Title').value,analysis:document.getElementById('ca1Analysis').value,evidence:document.getElementById('ca1Evidence').value,reflection:document.getElementById('reflection').value,checks:[1,2,3,4].map(i=>document.getElementById('ca1Check'+i).checked)};localStorage.setItem('bece_ca1',JSON.stringify(data));localStorage.setItem('bece_reflection',data.reflection);document.getElementById('saveMsg').innerHTML='Saved.<br>已保存。<br>Yǐ bǎocún.';document.getElementById('dashPort').innerHTML='Started<br>已开始<br>Yǐ kāishǐ';document.getElementById('dashCA1Top').textContent='Started';document.getElementById('ca1Status').innerHTML='Work saved<br>已保存作业<br>Yǐ bǎocún zuòyè'}
function markCA1Ready(){let data=JSON.parse(localStorage.getItem('bece_ca1')||'{}');data.checks=[1,2,3,4].map(i=>document.getElementById('ca1Check'+i).checked);data.status=data.checks.every(Boolean)&&data.title&&data.analysis&&data.evidence&&data.reflection?'Ready for lecturer review':'Please complete all required sections';localStorage.setItem('bece_ca1',JSON.stringify(data));let ready=data.status==='Ready for lecturer review';document.getElementById('ca1Status').innerHTML=ready?'Ready for lecturer review<br>准备好供讲师查看<br>Zhǔnbèi hǎo gōng jiǎngshī chákàn':'Please complete all required sections<br>请完成所有必需部分<br>Qǐng wánchéng suǒyǒu bìxū bùfen';document.getElementById('dashPort').innerHTML=ready?'Ready for review<br>准备查看<br>Zhǔnbèi chákàn':'Started<br>已开始<br>Yǐ kāishǐ';document.getElementById('dashCA1Top').textContent=ready?'Ready for review':'Started'}
function setupAccessibility(){document.querySelectorAll('.nav button').forEach(b=>{b.setAttribute('aria-label',b.textContent.replace(/\s+/g,' ').trim());b.setAttribute('aria-current',b.classList.contains('active')?'page':'false')});document.querySelectorAll('input,textarea').forEach(e=>{if(!e.getAttribute('aria-label')){let text=e.getAttribute('placeholder')||e.closest('.checkRow')?.querySelector('span')?.textContent||'';if(text)e.setAttribute('aria-label',text.replace(/\s+/g,' ').trim())}});document.querySelectorAll('.topicCard').forEach((c,i)=>{let done=JSON.parse(localStorage.getItem('bece_done')||'[]').includes(i);c.classList.toggle('is-complete',done);c.setAttribute('aria-current',done?'true':'false')});['quizResult','saveMsg','ca1Status'].forEach(id=>{let e=document.getElementById(id);if(e)e.setAttribute('aria-live','polite')})}
function showView(id){document.querySelectorAll('.view').forEach(x=>x.classList.remove('active'));let target=document.getElementById(id);if(target)target.classList.add('active');document.querySelectorAll('.nav button').forEach(x=>{let active=x.dataset.view===id;x.classList.toggle('active',active);x.setAttribute('aria-current',active?'page':'false')});let main=document.getElementById('mainContent');if(main)main.focus({preventScroll:true});window.scrollTo({top:0,behavior:window.matchMedia('(prefers-reduced-motion: reduce)').matches?'auto':'smooth'});setupAccessibility()}
document.addEventListener('keydown',e=>{if(e.key==='Escape'&&document.getElementById('toolPanel')?.innerHTML){closeTool();document.querySelector('.toolItem button')?.focus()}});
new MutationObserver(()=>setupAccessibility()).observe(document.getElementById('app'),{childList:true,subtree:true});
